import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'theme_preference.dart';
class ThemeController extends ChangeNotifier { ThemeController(this._prefs); final SharedPreferences _prefs; ThemePreference _preference=ThemePreference.system; double _textScale=1; bool _reduceMotion=false; ThemePreference get preference=>_preference; double get textScale=>_textScale; bool get reduceMotion=>_reduceMotion; Future<void> load()async{_preference=ThemePreference.values.firstWhere((x)=>x.name==_prefs.getString('theme'),orElse:()=>ThemePreference.system);_textScale=_prefs.getDouble('text_scale')??1;_reduceMotion=_prefs.getBool('reduce_motion')??false;notifyListeners();} Future<void> setTheme(ThemePreference x)async{_preference=x;await _prefs.setString('theme',x.name);notifyListeners();} Future<void> setTextScale(double x)async{_textScale=x.clamp(.85,1.6);await _prefs.setDouble('text_scale',_textScale);notifyListeners();} Future<void> setReduceMotion(bool x)async{_reduceMotion=x;await _prefs.setBool('reduce_motion',x);notifyListeners();}}
